const Z_LOWER = -1.6448536269514722;  // NORM.INV(1 - 0.95)
const Z_UPPER = 1.6448536269514722;   // NORM.INV(0.95)

function mulberry32(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randn(rng) {
  const u1 = Math.max(rng(), 1e-12);
  const u2 = rng();
  return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
}

function returnBoundary(mu, sigma, T, z) {
  const a = 1 + mu;
  return Math.exp(
    T * Math.log((a * a) / Math.sqrt(a * a + sigma * sigma)) +
    Math.sqrt(T) * Math.sqrt(Math.log((sigma / a) * (sigma / a) + 1)) * z,
  ) - 1;
}

function expectedReturnYears(mu, T) {
  return Math.pow(1 + mu, T) - 1;
}

function computeRiskReturn(weights, fundReturns, cov) {
  let er = 0;
  let variance = 0;
  const k = weights.length;
  for (let i = 0; i < k; i++) {
    const wi = weights[i];
    er += wi * fundReturns[i];
    const covRow = cov[i];
    for (let j = 0; j < k; j++) {
      variance += wi * weights[j] * covRow[j];
    }
  }
  return { risk: Math.sqrt(Math.max(0, variance)), expectedReturn: er };
}

function sampleScatter(fundReturns, cov, numSamples, seed) {
  const k = fundReturns.length;
  if (k === 0) return [];
  const rng = mulberry32(seed * 7919 + 31);
  const points = new Array(numSamples);
  const floats = new Array(k);
  const ints = new Array(k);
  const remOrder = new Array(k);
  const wArr = new Array(k);
  for (let s = 0; s < numSamples; s++) {
    // Dirichlet(1,…,1) sample on the continuous simplex
    let sum = 0;
    for (let i = 0; i < k; i++) {
      const u = Math.max(rng(), 1e-12);
      const x = -Math.log(u);
      floats[i] = x;
      sum += x;
    }
    // Largest-remainder rounding to integer percentages summing to 100
    let totalInt = 0;
    for (let i = 0; i < k; i++) {
      const pct = (floats[i] / sum) * 100;
      const flo = Math.floor(pct);
      ints[i] = flo;
      floats[i] = pct - flo;
      totalInt += flo;
      remOrder[i] = i;
    }
    const missing = 100 - totalInt;
    if (missing > 0) {
      remOrder.sort((a, b) => floats[b] - floats[a]);
      for (let i = 0; i < missing; i++) ints[remOrder[i]] += 1;
    }
    for (let i = 0; i < k; i++) wArr[i] = ints[i] / 100;
    points[s] = computeRiskReturn(wArr, fundReturns, cov);
  }
  return points;
}

function runSimulation(expectedReturnAnnual, stdDevAnnual, initial, years, numPaths, seed) {
  const months = years * 12;
  const dt = 1 / 12;
  const drift = (Math.log(1 + expectedReturnAnnual) - 0.5 * stdDevAnnual * stdDevAnnual) * dt;
  const vol = stdDevAnnual * Math.sqrt(dt);
  const rng = mulberry32(seed || 1);

  const paths = new Array(numPaths);
  for (let p = 0; p < numPaths; p++) {
    const path = new Array(months + 1);
    path[0] = initial;
    let v = initial;
    for (let m = 1; m <= months; m++) {
      v = v * Math.exp(drift + vol * randn(rng));
      path[m] = v;
    }
    paths[p] = path;
  }

  const finals = paths.map((p) => p[months]).sort((a, b) => a - b);

  const expectedPath = new Array(months + 1);
  const lowerBandPath = new Array(months + 1);
  const upperBandPath = new Array(months + 1);
  for (let m = 0; m <= months; m++) {
    const T = m / 12;
    expectedPath[m] = initial * (1 + expectedReturnYears(expectedReturnAnnual, T));
    lowerBandPath[m] = initial * (1 + returnBoundary(expectedReturnAnnual, stdDevAnnual, T, Z_LOWER));
    upperBandPath[m] = initial * (1 + returnBoundary(expectedReturnAnnual, stdDevAnnual, T, Z_UPPER));
  }

  return {
    paths, finals, months, initial,
    expectedFinal: expectedPath[months],
    lower90Final: lowerBandPath[months],
    upper90Final: upperBandPath[months],
    expectedPath, lowerBandPath, upperBandPath,
  };
}

self.onmessage = (e) => {
  const req = e.data;
  const sim = runSimulation(
    req.expectedReturn, req.risk, req.initial, req.years, req.numPaths, req.seed,
  );
  const scatter = sampleScatter(
    req.fundExpectedReturns, req.fundCovariance, req.numScatterSamples, req.seed,
  );
  self.postMessage({ id: req.id, sim, scatter });
};
